h=w=20
g=[[0]*w for _ in range(h)]
# block
for r in range(2,9):
 for c in range(9,16): g[r][c]=2
# markers
marks=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in marks:g[r][c]=1
# extend up
for r in range(0,2):
 for c in range(9,16):g[r][c]=2
# extend left/right for each object row if no marker on that respective side
for r in range(2,9):
 if not any(rr==r and c<9 for rr,c in marks):
  for c in range(0,9):g[r][c]=2
 if not any(rr==r and c>15 for rr,c in marks):
  for c in range(16,20):g[r][c]=2
# bottom each column
for c in range(9,16):
 if not any(cc==c and rr>8 for rr,cc in marks):
  for r in range(9,20):g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
